// Login.jsx
import React, { useEffect, useState } from "react";

export default function Login() {
  const [scriptLoaded, setScriptLoaded] = useState(false);

  useEffect(() => {
    // Agar script already loaded ho to skip
    if (window.google) {
      setScriptLoaded(true);
      return;
    }

    const script = document.createElement("script");
    script.src = "https://accounts.google.com/gsi/client";
    script.async = true;
    script.defer = true;
    script.onload = () => {
      // script ready
      setScriptLoaded(true);
      console.log("Google Identity script loaded");
    };
    script.onerror = () => {
      console.error("Failed to load Google Identity script");
    };
    document.head.appendChild(script);

    // cleanup optional
    return () => {
      // don't remove script on unmount, keeps it for entire app
    };
  }, []);

  const handleGoogleResponse = (response) => {
    if (!response?.credential) {
      console.error("No credential in response", response);
      return;
    }
    try {
      const decoded = JSON.parse(atob(response.credential.split(".")[1]));
      console.log("Google user:", decoded);
      alert(`Signed in as ${decoded.email}`);
    } catch (e) {
      console.error("Failed to decode token", e);
    }
  };

  const handleGoogleSignIn = () => {
    if (!scriptLoaded || !window.google) {
      alert("Google script not loaded yet. Try again in a moment.");
      return;
    }

    // Initialize only once is safe; calling multiple times also fine
    window.google.accounts.id.initialize({
      client_id: "284794061832-3cp9tbidnnp24obbtma1u17koe8oja5t.apps.googleusercontent.com",
      callback: handleGoogleResponse,
    });

    // This shows the one-tap prompt or popup flow.
    // Use prompt() to open the account chooser.
    window.google.accounts.id.prompt(); 
  };

  return (
    <div className="min-h-screen flex items-center justify-center bg-gray-100 p-4">
      <div className="bg-white w-full max-w-sm p-6 rounded-xl shadow-md">
        <h2 className="text-2xl font-semibold text-center mb-6">Login</h2>

        <button
          onClick={handleGoogleSignIn}
          className="w-full mt-4 flex items-center justify-center gap-2 border py-2 rounded-lg hover:bg-gray-50"
        >
          <img
            src="https://www.svgrepo.com/show/475656/google-color.svg"
            alt="Google"
            className="w-5 h-5"
          />
          Sign in with Google
        </button>
      </div>
    </div>
  );
}
